package com.hbm.machine.silex;
import com.hbm.recipe.generic.*;import com.mojang.serialization.MapCodec;import com.mojang.serialization.codecs.RecordCodecBuilder;import net.minecraft.core.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.Level;

/** Actual source material slurry recipe; weighted choice is deterministic137stride, not random collapse. */
public record SilexRecipe(GenericRecipeData data,int produced,int consumed,LaserWavelength wavelength) implements Recipe<RecipeInput>,GenericMachineRecipe {
 public static final MapCodec<SilexRecipe> CODEC=RecordCodecBuilder.mapCodec(i->i.group(GenericRecipeData.CODEC.fieldOf("data").forGetter(SilexRecipe::data),com.mojang.serialization.Codec.INT.fieldOf("produced").forGetter(SilexRecipe::produced),com.mojang.serialization.Codec.INT.fieldOf("consumed").forGetter(SilexRecipe::consumed),com.mojang.serialization.Codec.STRING.xmap(LaserWavelength::valueOf,LaserWavelength::name).fieldOf("wavelength").forGetter(SilexRecipe::wavelength)).apply(i,SilexRecipe::new));
 public java.util.List<GenericOutput.Chance> choices(){return outputItems().getFirst().pool();}
 public SilexRecipe tiny(){return new SilexRecipe(data,produced/900*100,consumed,wavelength);}
 @Override public boolean matches(RecipeInput input,Level level){return input.size()>0&&inputItems().getFirst().matches(input.getItem(0),true);}
 @Override public ItemStack assemble(RecipeInput input,HolderLookup.Provider lookup){return getResultItem(lookup).copy();}@Override public ItemStack getResultItem(HolderLookup.Provider lookup){return choices().getFirst().stack();}@Override public boolean isSpecial(){return true;}@Override public boolean canCraftInDimensions(int width,int height){return width*height>0;}@Override public NonNullList<Ingredient> getIngredients(){var list=NonNullList.<Ingredient>create();list.add(inputItems().getFirst().ingredient());return list;}@Override public RecipeType<?> getType(){return SilexContent.TYPE.get();}@Override public RecipeSerializer<?> getSerializer(){return SilexContent.SERIALIZER.get();}
 public static final class Serializer implements RecipeSerializer<SilexRecipe>{@Override public MapCodec<SilexRecipe> codec(){return CODEC;}@Override public StreamCodec<RegistryFriendlyByteBuf,SilexRecipe> streamCodec(){return StreamCodec.of((b,r)->{GenericRecipeData.STREAM_CODEC.encode(b,r.data);b.writeInt(r.produced);b.writeInt(r.consumed);b.writeEnum(r.wavelength);},b->new SilexRecipe(GenericRecipeData.STREAM_CODEC.decode(b),b.readInt(),b.readInt(),b.readEnum(LaserWavelength.class)));}}
}
